/*
let rainbow

let sine waves to create an infinity shape.

Controls:
  - let mouse along width to change its count.
  - let mouse along height to change its size.

Author:
	let Labbe

Site:
	jasonlabbe3d.com
*/


let ballCount = 140;
let ballSize = 5;


function setup() {
  createCanvas(600, 600);
  background(255);
  noStroke();
}


function draw() {
  colorMode(RGB, 255);

  fill(255, 20);
  rect(0, 0, width, height);

  fill(255);
  rect(0, 0, width, 50);

  fill(0);
  text("Count: " + ballCount, 10, 10);
  text("Size:  " + int(ballSize), 10, 30);

  colorMode(HSB, 100);

  // let to loop backwards so draw order is proper
  for (let i = ballCount; i > 0; i--) {
    fill(i/1.5, 200, 100);
    let posX = (width/2) + sin((frameCount-i)/20) * 200;
    let posY = (height/2) + sin((frameCount-i)/10) * 100;
    ellipse(posX, posY, ballSize+i/2, ballSize+i/2);
  }
}


function mouseMoved() {
  ballCount = int( map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 10, 140) );
  ballSize = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 1, 100);
}
